import assert from 'node:assert/strict';
import { ToyRoomTutorial } from '../src/js/toy-room/ToyRoomTutorial.js';
import { createToyRoomTutorialContext } from '../src/js/toy-room/ToyRoomTutorialContext.js';

const allowed = new Set(['mobilePresentation','player','fairy','toys','cameraX','cameraY','toyRoomTutorialCompleted','gameplayState']);
const room = { mobilePresentation:false, player:{x:100,y:400,carriedItem:null},
  fairy:{x:130,y:295}, toys:[{id:'primeiro',x:130,y:400}], cameraX:20,cameraY:30,
  toyRoomTutorialCompleted:false,gameplayState:'TOY_ROOM_GAMEPLAY' };
const restricted = new Proxy(room, {
  get(target,key) { assert.ok(allowed.has(key), `Leitura fora do contrato: ${String(key)}`); return target[key]; },
  set(target,key,value) { assert.ok(['toyRoomTutorialCompleted','gameplayState'].includes(key), `Escrita fora do contrato: ${String(key)}`); target[key]=value;return true; }
});
const context=createToyRoomTutorialContext(restricted), tutorial=new ToyRoomTutorial(context);
assert.deepEqual(new Set(Object.keys(context)),allowed);
assert.equal(tutorial.context,context);
assert.notEqual(tutorial.context,room);
assert.equal(tutorial.phase,undefined);
tutorial.start();assert.equal(room.gameplayState,'TOY_ROOM_TUTORIAL');
assert.equal(tutorial.step,'movement');room.player.x+=3;tutorial.update(1);
assert.equal(tutorial.step,'pickup');assert.equal(tutorial.target.id,'primeiro');
assert.equal(tutorial.message,'PRESSIONE E PARA PEGAR');
// Simula a substituição feita por restore sem reconstruir o tutorial/contexto.
const retiredPlayer=room.player,retiredToy=room.toys[0];
room.player={x:500,y:700,carriedItem:null};room.toys=[{id:'restaurado',x:540,y:700}];
room.fairy={x:540,y:595};room.cameraX=111;room.cameraY=222;
tutorial.start();room.player.x+=3;tutorial.update(1);
assert.equal(tutorial.target,room.toys[0]);assert.notEqual(tutorial.target,retiredToy);
assert.equal(context.player,room.player);assert.equal(context.fairy,room.fairy);
assert.equal(context.cameraX,111);assert.equal(context.cameraY,222);
assert.equal(retiredPlayer.x,103);
for (const [device,message] of [['MOBILE_TOUCH','TOQUE NO BOTÃO PEGAR'],['GAMEPAD','PRESSIONE X PARA PEGAR']]) {
  tutorial.setDevice(device);assert.equal(tutorial.message,message);
}
room.player.carriedItem=room.toys[0];tutorial.update(1);
assert.equal(tutorial.active,false);assert.equal(room.toyRoomTutorialCompleted,true);
assert.equal(room.gameplayState,'TOY_ROOM_GAMEPLAY');tutorial.start();assert.equal(tutorial.active,false);
assert.equal(room.toys[0].isOrganized,undefined);
console.log('APROVADO: contrato restrito, referências substituídas, mensagens por dispositivo e conclusão do tutorial sem alterar brinquedos.');
